<?php
declare(strict_types=1);
require __DIR__ . '/_bootstrap.php';
if (!admin_configured()) { header('Location: /admin/install.php'); exit; }
$db = admin_db();
$view = preg_replace('/[^a-z-]/', '', $_GET['view'] ?? 'dashboard');
$flash = pull_flash();
$error = '';

if ($view === 'logout') { session_destroy(); header('Location: /admin/?view=login'); exit; }
if ($view === 'login') {
    if (admin_user()) redirect_admin('dashboard');
    if (($_SERVER['REQUEST_METHOD'] ?? '') === 'POST') {
        try {
            verify_csrf();
            $email = strtolower(trim((string) ($_POST['email'] ?? '')));
            $s = $db->prepare('SELECT id,name,email,password_hash,role FROM admin_users WHERE email=? AND is_active=1 LIMIT 1');
            $s->execute([$email]); $found = $s->fetch();
            if (!$found || !password_verify((string) ($_POST['password'] ?? ''), $found['password_hash'])) throw new RuntimeException('Correo o contraseña incorrectos.');
            unset($found['password_hash']); session_regenerate_id(true); $_SESSION['admin'] = $found;
            $db->prepare('UPDATE admin_users SET last_login_at=NOW() WHERE id=?')->execute([$found['id']]);
            redirect_admin('dashboard');
        } catch (Throwable $exception) { $error = $exception->getMessage(); }
    }
    ?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Acceso | Royal Beans Perú</title><link rel="stylesheet" href="/admin/admin.css"></head><body class="auth-body"><main class="login-card"><img src="/images/logo.webp" alt="Royal Beans Perú"><p class="admin-eyebrow">Panel administrativo</p><h1>Bienvenido</h1><p>Gestiona productos, contenidos e imágenes desde un solo lugar.</p><?php if ($flash): ?><div class="alert <?=e($flash[0])?>"><?=e($flash[1])?></div><?php endif; ?><?php if ($error): ?><div class="alert error"><?=e($error)?></div><?php endif; ?><form method="post" class="admin-form"><?=csrf_field()?><label>Correo<input type="email" name="email" autocomplete="username" required></label><label>Contraseña<input type="password" name="password" autocomplete="current-password" required></label><button class="primary-button" type="submit">Iniciar sesión</button></form><a class="back-site" href="/">Volver al sitio</a></main></body></html><?php exit;
}

$user = require_admin();
if (in_array($view, ['content','content-edit','editor'], true)) { header('Location: /admin/editor.php'); exit; }
if (($_SERVER['REQUEST_METHOD'] ?? '') === 'POST') {
    try {
        verify_csrf();
        $action = (string) ($_POST['action'] ?? '');
        if ($action === 'save-product') {
            $id = (int) ($_POST['id'] ?? 0); $nameEs = trim((string) ($_POST['name_es'] ?? '')); $nameEn = trim((string) ($_POST['name_en'] ?? ''));
            if ($nameEs === '' || $nameEn === '') throw new RuntimeException('Completa el nombre en ambos idiomas.');
            $image = save_upload($db, $_FILES['image'] ?? [], (int) $user['id']) ?: trim((string) ($_POST['image_path'] ?? ''));
            if ($image === '' || !str_starts_with($image, '/')) throw new RuntimeException('Selecciona una imagen válida.');
            $db->beginTransaction();
            if ($id) {
                $db->prepare('UPDATE products SET line_id=?,category_id=?,image_path=?,is_active=?,featured_home=?,sort_order=? WHERE id=?')->execute([(int)$_POST['line_id'],(int)$_POST['category_id'],$image,isset($_POST['is_active']),isset($_POST['featured_home']),(int)$_POST['sort_order'],$id]);
            } else {
                $db->prepare('INSERT INTO products (line_id,category_id,image_path,is_active,featured_home,sort_order) VALUES (?,?,?,?,?,?)')->execute([(int)$_POST['line_id'],(int)$_POST['category_id'],$image,isset($_POST['is_active']),isset($_POST['featured_home']),(int)$_POST['sort_order']]);
                $id = (int) $db->lastInsertId();
            }
            $translation = $db->prepare('INSERT INTO product_translations (product_id,locale,name,slug,short_description,description,seo_title,seo_description) VALUES (?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE name=VALUES(name),slug=VALUES(slug),short_description=VALUES(short_description),description=VALUES(description),seo_title=VALUES(seo_title),seo_description=VALUES(seo_description)');
            foreach (['es','en'] as $locale) $translation->execute([$id,$locale,${'name'.ucfirst($locale)},admin_slug(${'name'.ucfirst($locale)}) . '-' . $id,trim((string)$_POST['short_'.$locale]),trim((string)$_POST['description_'.$locale]),trim((string)$_POST['seo_title_'.$locale]),trim((string)$_POST['seo_description_'.$locale])]);
            audit($db,(int)$user['id'],'save','product',$id,['line'=>(int)$_POST['line_id']]); $db->commit(); flash('success','Producto guardado y publicado en las secciones correspondientes.'); redirect_admin('products');
        }
        if ($action === 'delete-product') {
            $id = (int) $_POST['id']; $db->prepare('UPDATE products SET deleted_at=NOW(),is_active=0 WHERE id=?')->execute([$id]); audit($db,(int)$user['id'],'delete','product',$id); flash('success','Producto retirado. Puedes conservar su historial en la base de datos.'); redirect_admin('products');
        }
        if ($action === 'save-content') {
            $id = (int) ($_POST['id'] ?? 0); $values = [trim((string)$_POST['page_key']),trim((string)$_POST['section_key']),trim((string)$_POST['field_key']),$_POST['field_type'],trim((string)$_POST['label']),trim((string)$_POST['value_es']),trim((string)$_POST['value_en']),(int)$user['id']];
            if (!$values[0] || !$values[1] || !$values[2] || !$values[4]) throw new RuntimeException('Completa la identificación del contenido.');
            if ($id) { $values[]=$id; $db->prepare('UPDATE content_fields SET page_key=?,section_key=?,field_key=?,field_type=?,label=?,value_es=?,value_en=?,updated_by=? WHERE id=?')->execute($values); }
            else $db->prepare('INSERT INTO content_fields (page_key,section_key,field_key,field_type,label,value_es,value_en,updated_by) VALUES (?,?,?,?,?,?,?,?)')->execute($values);
            audit($db,(int)$user['id'],'save','content',$id ?: $db->lastInsertId()); flash('success','Contenido guardado.'); redirect_admin('content');
        }
        if ($action === 'upload-media') { $path=save_upload($db,$_FILES['image'] ?? [],(int)$user['id']); audit($db,(int)$user['id'],'upload','media',$path); flash('success','Imagen añadida a la biblioteca.'); redirect_admin('media'); }
        if ($action === 'save-settings') {
            $s=$db->prepare('INSERT INTO settings (setting_key,value_text,is_public) VALUES (?,?,1) ON DUPLICATE KEY UPDATE value_text=VALUES(value_text)');
            foreach (['company_email','company_phone','whatsapp','instagram','facebook','address_es','address_en'] as $key) $s->execute([$key,trim((string)($_POST[$key] ?? ''))]);
            audit($db,(int)$user['id'],'save','settings'); flash('success','Configuración actualizada.'); redirect_admin('settings');
        }
        if ($action === 'save-user') {
            if ($user['role'] !== 'admin') throw new RuntimeException('Solo un administrador puede crear usuarios.');
            $password=(string)$_POST['password']; if (strlen($password)<10) throw new RuntimeException('La contraseña debe tener al menos 10 caracteres.');
            $db->prepare('INSERT INTO admin_users (name,email,password_hash,role) VALUES (?,?,?,?)')->execute([trim((string)$_POST['name']),strtolower(trim((string)$_POST['email'])),password_hash($password,PASSWORD_DEFAULT),$_POST['role']==='admin'?'admin':'editor']);
            audit($db,(int)$user['id'],'create','user',$db->lastInsertId()); flash('success','Usuario creado.'); redirect_admin('users');
        }
        if ($action === 'inquiry-status') { $db->prepare('UPDATE inquiries SET status=? WHERE id=?')->execute([in_array($_POST['status'],['new','contacted','closed','spam'],true)?$_POST['status']:'new',(int)$_POST['id']]); redirect_admin('inquiries'); }
    } catch (Throwable $exception) { if ($db->inTransaction()) $db->rollBack(); $error = $exception->getMessage(); }
}

$nav = ['dashboard'=>'Resumen','products'=>'Productos','editor'=>'Editor visual','media'=>'Imágenes','inquiries'=>'Consultas','settings'=>'Configuración'];
if ($user['role']==='admin') $nav['users']='Usuarios';
function scalar(PDO $db,string $sql): int { return (int) $db->query($sql)->fetchColumn(); }
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($nav[$view] ?? 'Administración')?> | Royal Beans Perú</title><link rel="stylesheet" href="/admin/admin.css"></head><body class="admin-body"><aside class="admin-sidebar"><a class="admin-brand" href="/admin/"><img src="/images/logo.webp" alt=""><span><strong>ROYAL BEANS</strong><small>ADMINISTRACIÓN</small></span></a><nav><?php foreach($nav as $key=>$label): ?><a class="<?=$view===$key?'active':''?>" href="<?=$key==='editor'?'/admin/editor.php':'/admin/?view='.e($key)?>"><?=e($label)?></a><?php endforeach; ?></nav><div class="admin-user"><strong><?=e($user['name'])?></strong><small><?=e($user['role'])?></small><a href="/admin/?view=logout">Cerrar sesión</a></div></aside><main class="admin-main"><header class="admin-top"><div><p class="admin-eyebrow">Panel de gestión</p><h1><?=e($nav[$view] ?? ($view==='product-edit'?'Editar producto':'Administración'))?></h1></div><a class="site-button" href="/" target="_blank">Ver sitio ↗</a></header><?php if ($flash): ?><div class="alert <?=e($flash[0])?>"><?=e($flash[1])?></div><?php endif; ?><?php if ($error): ?><div class="alert error"><?=e($error)?></div><?php endif; ?>

<?php if ($view==='dashboard'): $counts=['Productos activos'=>scalar($db,'SELECT COUNT(*) FROM products WHERE is_active=1 AND deleted_at IS NULL'),'Productos Retail'=>scalar($db,"SELECT COUNT(*) FROM products p JOIN product_lines l ON l.id=p.line_id WHERE l.slug='retail' AND p.is_active=1 AND p.deleted_at IS NULL"),'Consultas nuevas'=>scalar($db,"SELECT COUNT(*) FROM inquiries WHERE status='new'"),'Imágenes'=>scalar($db,'SELECT COUNT(*) FROM media')]; ?><section class="stat-grid"><?php foreach($counts as $label=>$count): ?><article><span><?=e($count)?></span><h2><?=e($label)?></h2></article><?php endforeach; ?></section><section class="admin-panel"><h2>Acciones rápidas</h2><div class="quick-actions"><a href="/admin/?view=product-edit">Añadir producto</a><a href="/admin/editor.php">Abrir editor visual</a><a href="/admin/?view=media">Subir imagen</a></div></section>

<?php elseif ($view==='products'): $line=$_GET['line']??''; $params=[]; $where='p.deleted_at IS NULL'; if(in_array($line,['conventional','retail'],true)){$where.=' AND l.slug=?';$params[]=$line;} $s=$db->prepare("SELECT p.id,p.image_path,p.is_active,p.featured_home,p.sort_order,l.name_es line_name,c.name_es category,MAX(CASE WHEN t.locale='es' THEN t.name END) name_es,MAX(CASE WHEN t.locale='en' THEN t.name END) name_en FROM products p JOIN product_lines l ON l.id=p.line_id JOIN product_categories c ON c.id=p.category_id JOIN product_translations t ON t.product_id=p.id WHERE $where GROUP BY p.id,p.image_path,p.is_active,p.featured_home,p.sort_order,l.name_es,c.name_es ORDER BY l.sort_order,p.sort_order,p.id");$s->execute($params);$rows=$s->fetchAll(); ?><div class="toolbar"><div class="filters"><a class="<?=!$line?'active':''?>" href="/admin/?view=products">Todos</a><a class="<?=$line==='conventional'?'active':''?>" href="/admin/?view=products&line=conventional">Convencional</a><a class="<?=$line==='retail'?'active':''?>" href="/admin/?view=products&line=retail">Retail</a></div><a class="primary-button" href="/admin/?view=product-edit">Añadir producto</a></div><section class="admin-panel table-wrap"><table><thead><tr><th>Imagen</th><th>Producto</th><th>Línea</th><th>Categoría</th><th>Estado</th><th>Inicio</th><th></th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><img class="thumb" src="<?=e($row['image_path'])?>" alt=""></td><td><strong><?=e($row['name_es'])?></strong><small><?=e($row['name_en'])?></small></td><td><?=e($row['line_name'])?></td><td><?=e($row['category'])?></td><td><span class="status <?=$row['is_active']?'published':'draft'?>"><?=$row['is_active']?'Publicado':'Oculto'?></span></td><td><?=$row['featured_home']?'Sí':'—'?></td><td class="actions"><a href="/admin/?view=product-edit&id=<?=$row['id']?>">Datos</a><a href="/admin/product-details.php?id=<?=$row['id']?>">Ficha</a><form method="post" onsubmit="return confirm('¿Retirar este producto?')"><?=csrf_field()?><input type="hidden" name="action" value="delete-product"><input type="hidden" name="id" value="<?=$row['id']?>"><button>Eliminar</button></form></td></tr><?php endforeach; ?></tbody></table></section>

<?php elseif ($view==='product-edit'): $id=(int)($_GET['id']??0);$product=['id'=>0,'line_id'=>'','category_id'=>'','image_path'=>'','is_active'=>1,'featured_home'=>1,'sort_order'=>100,'name_es'=>'','name_en'=>'','short_es'=>'','short_en'=>'','description_es'=>'','description_en'=>'','seo_title_es'=>'','seo_title_en'=>'','seo_description_es'=>'','seo_description_en'=>'']; if($id){$s=$db->prepare("SELECT p.*,MAX(CASE WHEN t.locale='es' THEN t.name END) name_es,MAX(CASE WHEN t.locale='en' THEN t.name END) name_en,MAX(CASE WHEN t.locale='es' THEN t.short_description END) short_es,MAX(CASE WHEN t.locale='en' THEN t.short_description END) short_en,MAX(CASE WHEN t.locale='es' THEN t.description END) description_es,MAX(CASE WHEN t.locale='en' THEN t.description END) description_en,MAX(CASE WHEN t.locale='es' THEN t.seo_title END) seo_title_es,MAX(CASE WHEN t.locale='en' THEN t.seo_title END) seo_title_en,MAX(CASE WHEN t.locale='es' THEN t.seo_description END) seo_description_es,MAX(CASE WHEN t.locale='en' THEN t.seo_description END) seo_description_en FROM products p JOIN product_translations t ON t.product_id=p.id WHERE p.id=? GROUP BY p.id");$s->execute([$id]);$product=$s->fetch()?:$product;} $lines=$db->query('SELECT * FROM product_lines WHERE is_active=1 ORDER BY sort_order')->fetchAll();$categories=$db->query('SELECT * FROM product_categories WHERE is_active=1 ORDER BY sort_order')->fetchAll(); ?><form method="post" enctype="multipart/form-data" class="admin-panel admin-form product-form"><?=csrf_field()?><input type="hidden" name="action" value="save-product"><input type="hidden" name="id" value="<?=e($product['id'])?>"><div class="form-grid"><label>Línea<select name="line_id" required><?php foreach($lines as $item): ?><option value="<?=$item['id']?>" <?=$product['line_id']==$item['id']?'selected':''?>><?=e($item['name_es'])?></option><?php endforeach; ?></select></label><label>Categoría<select name="category_id" required><?php foreach($categories as $item): ?><option value="<?=$item['id']?>" <?=$product['category_id']==$item['id']?'selected':''?>><?=e($item['name_es'])?></option><?php endforeach; ?></select></label><label>Orden<input type="number" name="sort_order" value="<?=e($product['sort_order'])?>"></label><label class="check"><input type="checkbox" name="is_active" <?=$product['is_active']?'checked':''?>> Publicado</label><label class="check"><input type="checkbox" name="featured_home" <?=$product['featured_home']?'checked':''?>> Mostrar en Inicio</label></div><div class="language-grid"><fieldset><legend>Español</legend><label>Nombre<input name="name_es" value="<?=e($product['name_es'])?>" required></label><label>Descripción corta<textarea name="short_es" rows="2"><?=e($product['short_es'])?></textarea></label><label>Descripción completa<textarea name="description_es" rows="4"><?=e($product['description_es'])?></textarea></label><label>Título SEO<input name="seo_title_es" value="<?=e($product['seo_title_es'])?>"></label><label>Descripción SEO<textarea name="seo_description_es" rows="2"><?=e($product['seo_description_es'])?></textarea></label></fieldset><fieldset><legend>English</legend><label>Name<input name="name_en" value="<?=e($product['name_en'])?>" required></label><label>Short description<textarea name="short_en" rows="2"><?=e($product['short_en'])?></textarea></label><label>Full description<textarea name="description_en" rows="4"><?=e($product['description_en'])?></textarea></label><label>SEO title<input name="seo_title_en" value="<?=e($product['seo_title_en'])?>"></label><label>SEO description<textarea name="seo_description_en" rows="2"><?=e($product['seo_description_en'])?></textarea></label></fieldset></div><div class="image-field"><?php if($product['image_path']):?><img src="<?=e($product['image_path'])?>" alt="Vista actual"><?php endif;?><div><label>Ruta actual<input name="image_path" value="<?=e($product['image_path'])?>" placeholder="/uploads/..."></label><label>Nueva imagen<input type="file" name="image" accept="image/jpeg,image/png,image/webp,image/avif"><small>Cuadrada, recomendada: 1200 × 1200 px. Máximo 8 MB.</small></label></div></div><div class="form-actions"><a href="/admin/?view=products">Cancelar</a><button class="primary-button" type="submit">Guardar producto</button></div></form>

